// План specs/google-maps-mobile.md 1.1–1.4 (кейсы GM-01…GM-04). Admin, компания «test». Только просмотр.
// Реальное приложение Google Maps в эмуляции не открыть — проверяем адрес навигации (window.open / href, новая вкладка).
// Переход на google.com/maps заблокирован (trapExternalMaps), ссылки не нажимаем.
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, setEnglish } from '../addresses/address-helpers';
import { TEST_CLIENT_ID } from '../addresses/address-display-helpers';
import {
  GMAPS_DIR, TEST_LEAD, gmapsDirLinks, leadCard, openJobPreview, openLeadDetails, openLeadsMap, openedUrls, trapExternalMaps,
} from '../leads-map/map-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Телефон: адрес и «View on Map» открывают навигацию Google Maps (#6e6f101d)', () => {
  test.beforeEach(async ({ page }) => {
    await setEnglish(page);
    await trapExternalMaps(page);
  });

  test('Map on phone: "View on Map" opens Google Maps directions to the lead address, card address is a directions link #6e6f101d @android @prod-safe', async ({ page }) => {
    await openLeadsMap(page);
    const expectedUrl = GMAPS_DIR + encodeURIComponent(TEST_LEAD.address);

    // Адрес в карточке лида — ссылка навигации в новой вкладке.
    const link = gmapsDirLinks(leadCard(page, TEST_LEAD.name, TEST_LEAD.phone));
    await expect(link).toHaveCount(1);
    await expect(link).toHaveText(TEST_LEAD.address);
    await expect(link).toHaveAttribute('href', expectedUrl);
    await expect(link).toHaveAttribute('target', '_blank');

    // «View on Map» — не центрирует карту, а открывает навигацию (window.open).
    await page.getByRole('button', { name: 'View on Map' }).first().click();
    await expect.poll(() => openedUrls(page), { message: 'window.open после «View on Map»' }).toContain(expectedUrl);
    await expect(page).toHaveURL(/\/map$/);
  });

  test('Leads on phone: address in Lead Details is a Google Maps directions link #6e6f101d @android @prod-safe', async ({ page }) => {
    const dialog = await openLeadDetails(page, TEST_LEAD.phone);
    const link = gmapsDirLinks(dialog);
    await expect(link).toHaveCount(1);
    await expect(link).toHaveText(TEST_LEAD.address);
    await expect(link).toHaveAttribute('href', new RegExp('^' + GMAPS_DIR.replace(/[.?/]/g, '\\$&') + encodeURIComponent(TEST_LEAD.address)));
    await expect(link).toHaveAttribute('target', '_blank');
  });

  test('Jobs on phone: address in Job Preview is a Google Maps directions link #6e6f101d @android @prod-safe', async ({ page }) => {
    // JOB-0011 (клиент «test», Completed) — адрес «2221 NW Federal Hwy, Unit 1234, …».
    const dialog = await openJobPreview(page, 'Completed', 'JOB-0011');
    const link = gmapsDirLinks(dialog);
    await expect(link).toHaveCount(1);
    await expect(link).toContainText('2221 NW Federal Hwy');
    await expect(link).toHaveAttribute('href', new RegExp(encodeURIComponent('2221 NW Federal Hwy')));
    await expect(link).toHaveAttribute('target', '_blank');
  });

  test('Client page on phone: address in the header is a Google Maps directions link #6e6f101d @android @prod-safe', async ({ page }) => {
    await page.goto(`/CustomerDetail?id=${TEST_CLIENT_ID}`);
    const link = gmapsDirLinks(page.locator('main')).first();
    await expect(link).toBeVisible();
    await expect(link).toContainText('2221 NW Federal Hwy');
    await expect(link).toHaveAttribute('href', new RegExp(encodeURIComponent('2221 NW Federal Hwy')));
    await expect(link).toHaveAttribute('target', '_blank');
  });
});
